-- XOR function (works on all executors)
local function X(a,b)
 local r,p=0,1
 while a>0 or b>0 do
  if a%2~=b%2 then r=r+p end
  a=math.floor(a/2)b=math.floor(b/2)p=p*2
 end
 return r
end

-- XOR entire string
local function XS(s,k)
 local o={}
 local kl=#k
 for i=1,#s do
  o[i]=string.char(X(s:byte(i),k:byte((i-1)%kl+1)))
 end
 return table.concat(o)
end

-- Base64 decode
local function D(s)
 local c="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
 local t={}
 for i=1,#c do t[c:byte(i)]=i-1 end
 local o={}
 local a=0
 local n=0
 for p=1,#s do
  local v=t[s:byte(p)]
  if v then
   a=a*64+v
   n=n+1
   if n==4 then
    o[#o+1]=string.char(math.floor(a/65536)%256)
    o[#o+1]=string.char(math.floor(a/256)%256)
    o[#o+1]=string.char(a%256)
    a=0;n=0
   end
  end
 end
 if n==2 then
  a=a*64
  o[#o+1]=string.char(math.floor(a/65536)%256)
 elseif n==3 then
  a=a*64
  o[#o+1]=string.char(math.floor(a/65536)%256)
  o[#o+1]=string.char(math.floor(a/256)%256)
 end
 return table.concat(o)
end

